kata.solucion:
function sumar3(a: number, b: number, c: number): number {
  return a + b + c;
}

export function curry(fn: (...args: number[]) => number): (...args: number[]) => unknown {
  // Acumula argumentos hasta tener los que declara fn (fn.length) y entonces la llama.
  const acumular =
    (previos: number[]) =>
    (...nuevos: number[]): unknown => {
      const args = [...previos, ...nuevos];
      return args.length >= fn.length ? fn(...args) : acumular(args);
    };
  return acumular([]);
}

// probarCurry la usa el runner: aplica los grupos de argumentos en orden
// sobre curry(sumar3) hasta obtener el resultado numérico final.
export function probarCurry(gruposDeArgumentos: number[][]): number {
  let actual: unknown = curry(sumar3);
  for (const grupo of gruposDeArgumentos) {
    actual = (actual as (...args: number[]) => unknown)(...grupo);
  }
  return actual as number;
}

