let vecesEjecutado = 0;

function costosa(a: number, b: number): number {
  vecesEjecutado++;
  return a + b;
}

export function memoize<F extends (...args: number[]) => number>(fn: F): F {
  // La clave son los argumentos serializados: [1, 2] y [1, 2] dan la misma.
  const cache = new Map<string, number>();
  return ((...args: number[]) => {
    const clave = JSON.stringify(args);
    if (!cache.has(clave)) cache.set(clave, fn(...args));
    return cache.get(clave)!;
  }) as F;
}

// probarMemoize la usa el runner: llama a memoize(costosa) con cada grupo
// de argumentos y devuelve los resultados junto con el contador real de ejecuciones.
export function probarMemoize(llamadas: number[][]): { resultados: number[]; vecesEjecutado: number } {
  vecesEjecutado = 0;
  const memoizada = memoize(costosa);
  const resultados = llamadas.map((args) => memoizada(...(args as [number, number])));
  return { resultados, vecesEjecutado };
}
